void assertPayrollGeometry(MyGUI::Widget* w,bool scroll=false){
 for(size_t i=0;i<w->children.size();++i){MyGUI::Widget* c=w->children[i];assert(c->w>0&&c->h>0&&c->x>=0&&c->y>=0);
  if(!scroll){if(c->x+c->w>w->w||c->y+c->h>w->h)std::cerr<<"overflow "<<c->type()<<" "<<c->x<<","<<c->y<<","<<c->w<<","<<c->h<<" parent "<<w->w<<","<<w->h<<"\n";assert(c->x+c->w<=w->w&&c->y+c->h<=w->h);}
  MyGUI::TextBox* t=dynamic_cast<MyGUI::TextBox*>(c);if(t&&!t->caption.empty()){if(t->getTextSize().width>c->w||t->getTextSize().height>c->h)std::cerr<<"text overflow: "<<t->caption<<" actual "<<t->getTextSize().width<<","<<t->getTextSize().height<<" box "<<c->w<<","<<c->h<<"\n";assert(t->getTextSize().width<=c->w&&t->getTextSize().height<=c->h);}
  assertPayrollGeometry(c,scroll||dynamic_cast<MyGUI::ScrollView*>(c)!=0);
 }
}
MyGUI::Button* action(MyGUI::Widget* w,const std::string& name){for(size_t i=0;i<w->children.size();++i){MyGUI::Widget* c=w->children[i];if(c->getUserString("payrollAction")==name)return dynamic_cast<MyGUI::Button*>(c);if(MyGUI::Button* found=action(c,name))return found;}return 0;}
bool containsText(MyGUI::Widget* w,const std::string& value){MyGUI::TextBox* t=dynamic_cast<MyGUI::TextBox*>(w);if(t&&t->caption.find(value)!=std::string::npos)return true;for(size_t i=0;i<w->children.size();++i)if(containsText(w->children[i],value))return true;return false;}
void click(MyGUI::Window* w,const std::string& name){MyGUI::Button* b=action(w,name);assert(b&&b->eventMouseButtonClick.callback==payrollUiClick);b->eventMouseButtonClick.callback(b);}
void sheetSnapshot(MyGUI::Widget* w,std::ofstream& f,int x,int y,int left,int top,int right,int bottom){
 x+=w->x;y+=w->y;MyGUI::TextBox* t=dynamic_cast<MyGUI::TextBox*>(w);MyGUI::ImageBox* icon=dynamic_cast<MyGUI::ImageBox*>(w);
 f<<w->type()<<"\t"<<x<<"\t"<<y<<"\t"<<w->w<<"\t"<<w->h<<"\t"<<w->colour.r<<"\t"<<w->colour.g<<"\t"<<w->colour.b<<"\t"<<(t?t->font:0)<<"\t"<<(t?t->align:0)<<"\t"<<(t?hex(t->caption):"")<<"\t"<<(icon?icon->texture:"")<<"\t"<<(icon?icon->uv.left:0)<<"\t"<<(icon?icon->uv.top:0)<<"\t"<<(icon?icon->uv.width:0)<<"\t"<<(icon?icon->uv.height:0)<<"\t"<<left<<"\t"<<top<<"\t"<<right<<"\t"<<bottom<<"\n";
 if(dynamic_cast<MyGUI::ScrollView*>(w)){left=std::max(left,x);top=std::max(top,y);right=std::min(right,x+w->w);bottom=std::min(bottom,y+w->h);}
 for(size_t i=0;i<w->children.size();++i)sheetSnapshot(w->children[i],f,x,y,left,top,right,bottom);
}
