float developerTimeOffsetHours=0;
MyGUI::Widget* guildWindow=0;MyGUI::Widget* missionBookContentText=0;
void updateDelegatedMission(){}void updateMailMissions(float){}
void updateGuildMenu(){}void refreshMissionBook(){}void updateTrackerUI(){}
    void developerAdvanceWorldTime(float hours)
    {
        if(hours<=0)return;
        // The developer clock also runs while simulation is paused. Establish
        // the current cycle before jumping, then service every crossed deadline
        // here instead of waiting for another simulation update.
        payrollSync();
        developerTimeOffsetHours+=hours;currentGameHours+=hours;
        payrollSync();updatePayrollWindows();
        updateDelegatedMission();updateMailMissions(2.0f);
        if(guildWindow&&guildWindow->getVisible())updateGuildMenu();
        if(missionBookContentText)refreshMissionBook();
        updateTrackerUI();
    }

void reloadPayroll(){MissionArchive out;guildPayroll.archive(out);closePayrollWindowsForWorld();guildPayroll=GuildPayroll::State();MissionArchive in(out.bytes);guildPayroll.archive(in);in.finish();}
void developerDays(int days){for(int i=0;i<days;++i)developerAdvanceWorldTime(24);}
